<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionObjectListRenderer implements ObjectListRenderer,CompatibilityObjectListRenderer
{
    public function render(HttpUser $user,array $objects):string
    {
        $e=[PilotView::class,'e'];$shown=\count($objects);$pagination=$objects[0]['_pagination']??['page'=>1,'pages'=>1,'total'=>$shown,'origin'=>'all'];$count=(int)$pagination['total'];$page=(int)$pagination['page'];$pages=(int)$pagination['pages'];$origin=(string)($pagination['origin']??'all');
        $body='<div class="fm2-page-header fm2-page-header--queue"><div><h1>Объекты монтажа</h1><p>Контроль подготовки и открытия монтажных работ</p></div><span class="fm2-result-count">'.$count.' '.($count===1?'объект':'объекта').'</span></div>';
        if($objects===[])$body.='<section class="shlz-empty-state fm2-empty"><strong>Сейчас нет объектов монтажа</strong><p>Импортированные объекты монтажа пока отсутствуют.</p><a class="shlz-link" href="/pilot/objects">Обновить страницу</a></section>';
        else{
            $labels=['migration_native'=>['Нативный импорт','shlz-status--bright-green'],'migration_active'=>['Активен с cutover','shlz-status--blue'],'demo_fixture'=>['Демо-данные','shlz-status--orange'],'local_audit'=>['Локальная проверка','shlz-status--orange']];$rows='';foreach($objects as$o){$id=$e($o['id']);$unknown=$o['planningDatesUnknownAtCutover']??false;$status=(string)($o['status']??($unknown?'В работе после cutover':'Требуется распоряжение'));$statusPaint=\str_contains($status,'работ')?'shlz-status--bright-green':'shlz-status--orange';$period=$unknown?'<span class="fm2-cell-main">Неизвестно на cutover</span><small>Даты не восстановлены</small>':'<span class="fm2-cell-main">'.PilotView::date($o['plannedStartDate']).'</span><small>до '.PilotView::date($o['plannedFinishDate']).'</small>';$source=$labels[$o['dataOrigin']??'local_audit'];$rows.='<tr data-origin="'.$e($o['dataOrigin']??'local_audit').'"><td data-label="Объект"><a class="fm2-object-link" href="/pilot/objects/'.$id.'"><strong>№ '.$id.'</strong><span class="fm2-db-text">'.$e($o['registrationNumber']).'</span></a><span class="shlz-status '.$source[1].' fm2-origin-badge">'.$source[0].'</span></td><td data-label="Адрес"><span class="fm2-cell-main fm2-db-text">'.$e($o['address']).'</span><small>Подъезд '.$e($o['entrance']).'</small></td><td data-label="Плановый период">'.$period.'</td><td data-label="Состояние"><span class="shlz-status '.$statusPaint.' fm2-status">'.$e($status).'</span></td><td data-label="Следующий шаг"><span class="fm2-cell-main">'.$e($o['nextStep']??($unknown?'Продолжить нативную историю':'Открыть карточку объекта')).'</span></td><td class="fm2-row-action"><span aria-hidden="true">→</span></td></tr>';}
            $filterLabels=['all'=>'Все','migration'=>'Только миграция','migration_native'=>'Нативный импорт','migration_active'=>'Активны с cutover','demo_fixture'=>'Демо','local_audit'=>'Локальные проверки'];$filters='';foreach($filterLabels as$value=>$label)$filters.='<a class="fm2-segment'.($origin===$value?' fm2-segment--active':'').'" href="/pilot/objects'.($value==='all'?'':'?origin='.$value).'"'.($origin===$value?' aria-current="page"':'').'>'.$label.'</a>';$query=$origin==='all'?[]:['origin'=>$origin];$pagination=PilotView::pagination('/pilot/objects',$page,$pages,'Страницы очереди объектов монтажа',$query);$body.='<section class="fm2-list-surface"><div class="fm2-list-toolbar"><nav class="fm2-segments" aria-label="Фильтр по происхождению данных">'.$filters.'</nav><a class="shlz-link" href="/pilot/objects'.($origin==='all'?'':'?origin='.$e($origin)).'">Обновить</a></div><div class="fm2-table-wrap"><table class="shlz-table fm2-queue-table"><thead><tr><th>Объект и источник</th><th>Адрес</th><th>Плановый период</th><th>Состояние</th><th>Следующий шаг</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div><footer class="fm2-table-footer"><span>Показано '.$shown.' из '.$count.'</span>'.$pagination.'</footer></section>';
        }
        return PilotView::document($user,'Объекты монтажа','Объекты монтажа','',$body);
    }
    public function renderCompatibility(HttpUser $user,array $objects):string{return $this->render($user,$objects);}
}
